{
"predictors": [
{
"name": "Internet Adoption Ratio",
"construction": "The proportion of a firm's operations or sales that are internet-based.",
"rationale": "Firms that are early adopters of the internet may be better positioned to gain competitive advantage in the new economy.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Product Lifecycle Stage",
"construction": "Estimated stage of a company's core product's lifecycle, based on sales growth and analyst reports.",
"rationale": "Firms with products in the growth stage may be poised for above-average earnings growth.",
"higher_returns_for": "Stocks in the growth stage of the product lifecycle"
},
{
"name": "Corporate Governance Score",
"construction": "Scores based on the quality of a firm's governance practices, using data from public filings and proxy statements.",
"rationale": "Firms with better governance may pose less risk and could be more likely to generate shareholder value over time.",
"higher_returns_for": "High corporate governance scores"
},
{
"name": "Workforce Education Level",
"construction": "Average education level of a firm's workforce, based on publicly-available demographic data.",
"rationale": "Firms with a more educated workforce may be more innovative and productive.",
"higher_returns_for": "High workforce education levels"
},
{
"name": "Brand Value Contribution",
"construction": "Estimated contribution of brand value to a firm's market cap, based on analyst estimates and brand surveys.",
"rationale": "Strong brands may reduce business risk and increase customer loyalty and pricing power.",
"higher_returns_for": "High brand value contributions"
},
{
"name": "Employee Satisfaction",
"construction": "Measure of employee satisfaction, using data from anonymous employee reviews on early internet job sites.",
"rationale": "Happier employees may result in better customer service and lower turnover costs.",
"higher_returns_for": "High employee satisfaction"
},
{
"name": "IP Portfolio Strength",
"construction": "Measure of the size and quality of a firm's intellectual property portfolio, based on patent filings and citations.",
"rationale": "A strong IP portfolio may provide a competitive advantage and potential for licensing revenue.",
"higher_returns_for": "Strong IP portfolios"
},
{
"name": "Environmental Sustainability Score",
"construction": "Scores based on a firm's environmental practices and impact, using data from public filings and third-party reports.",
"rationale": "Firms with strong environmental practices may pose less risk and attract investment from increasingly environmentally-conscious investors.",
"higher_returns_for": "High environmental sustainability scores"
},
{
"name": "Customer Retention Rate",
"construction": "Measure of a firm's customer retention rate, based on publicly-available customer data and management reports.",
"rationale": "High customer retention may indicate strong customer loyalty and reduce marketing and customer acquisition costs.",
"higher_returns_for": "High customer retention rates"
},
{
"name": "Supply Chain Efficiency",
"construction": "Measure of a firm's supply chain efficiency, based on logistics and operations data in public filings.",
"rationale": "An efficient supply chain can reduce costs and enable a firm to respond more quickly to market changes.",
"higher_returns_for": "High supply chain efficiency"
}
]
}
